mapper.select:
select u.id, u.name, u.sex, u.birth_year, u.height, u.hometown, u.current_city, u.education, u.phone, u.occupation, u.monthly_income, u.service_status, u.smoke_habit, u.drink_habit, u.has_car, u.has_house, u.has_tattoo, u.accept_long_dist, u.photos, u.status, u.del_flag, u.create_time, u.update_time from sys_paying_user u
u.del_flag = '0' and u.status = '0'
and u.id != #{payingId} and u.sex in ('0','1') and exists (select 1 from sys_paying_user p left join sys_user ps on ps.user_id=p.matchmaker_id where p.id=#{payingId} and p.del_flag='0' and p.sex in ('0','1') and p.sex != u.sex
and (case when p.matchmaker_id is null then p.create_by else ps.user_name end)=#{params.archiveOwner}
)
order by u.id desc
